package tests.base;
import tests.BaseTest;
import io.github.ccxt.Helpers;
import io.github.ccxt.Exchange;
import java.util.HashMap;


// PLEASE DO NOT EDIT THIS FILE, IT IS GENERATED AND WILL BE OVERWRITTEN:
